import type { QdrantClient } from '@qdrant/js-client-rest';
import type { Redis } from 'ioredis';

interface PublishVersionInput {
  collection: string;
  tenantId: string;
  docFamilyId: string;
  oldVersion: number;
  newVersion: number;
}

/**
 * Đóng dấu vô hiệu hóa toàn bộ vector cũ và xóa sạch Semantic Cache phụ thuộc < 100ms.
 * Điều kiện tiên quyết: các chunk của newVersion đã được upsert xong với status = 'staging'.
 */
export async function promoteVersionAndPurgeCache(
  qdrant: QdrantClient,
  redis: Redis,
  input: PublishVersionInput
): Promise<{ purgedCacheKeys: number }> {
  const { collection, tenantId, docFamilyId, oldVersion, newVersion } = input;

  // 1. Kích hoạt phiên bản mới trước để tránh bất kỳ mili-giây rỗng ngữ cảnh nào
  await qdrant.setPayload(collection, {
    payload: { status: 'active', activated_at: new Date().toISOString() },
    filter: {
      must: [
        { key: 'tenant_id', match: { value: tenantId } },
        { key: 'doc_family_id', match: { value: docFamilyId } },
        { key: 'doc_version', match: { value: newVersion } },
        { key: 'status', match: { value: 'staging' } },
      ],
    },
    wait: true,
  });

  // 2. Soft-Tombstone lập tức toàn bộ chunk phiên bản cũ (giữ lại 14 ngày để rollback/audit)
  await qdrant.setPayload(collection, {
    payload: { status: 'superseded', superseded_at: new Date().toISOString() },
    filter: {
      must: [
        { key: 'tenant_id', match: { value: tenantId } },
        { key: 'doc_family_id', match: { value: docFamilyId } },
        { key: 'doc_version', match: { value: oldVersion } },
        { key: 'status', match: { value: 'active' } },
      ],
    },
    wait: true,
  });

  // 3. Selective Semantic Cache Invalidation: chỉ xóa cache key từng trích dẫn docFamilyId này
  const depSetKey = `rag:cache_deps:${tenantId}:${docFamilyId}`;
  const dependentCacheKeys = await redis.smembers(depSetKey);

  if (dependentCacheKeys.length > 0) {
    const pipeline = redis.pipeline();
    pipeline.unlink(...dependentCacheKeys);
    pipeline.unlink(depSetKey);
    await pipeline.exec();
  }

  return { purgedCacheKeys: dependentCacheKeys.length };
}
